export function germanTourTitle(slug: string, fallback: string) {
  return germanTourOverrides[slug]?.title || fallback;
}

export function localizeTourGerman(tour: Tour): Tour {
  return { ...tour, ...germanTourOverrides[tour.slug] };
}

